mapper.select:
SELECT ch.id AS chapter_id,ch.title AS chapter_title,ch.course_id,p.completed_at,p.last_visited_at
FROM learning_chapter ch LEFT JOIN learning_chapter_progress p ON p.chapter_id=ch.id AND p.student_id=#{studentId}
WHERE ch.course_id=#{courseId} AND ch.deleted=0 AND ch.status='PUBLISHED' ORDER BY ch.sort_order,ch.id
